// Generates an OKF Site concept (docs/index.md) for one site from its
// build-plan.yaml — offline, deterministic, no Cloudflare calls. The Site
// concept is the entry point of the site's own OKF doc bundle. Contract:
// docs/knowledge/index.md.
//
//   node scripts/lib/generate-site-concept.mjs <build-plan.yaml> <out.md> [slug]
import fs from 'node:fs';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import yaml from 'js-yaml';

const GENERATED_NOTE =
  '<!-- Generated by scripts/generate-site-docs.sh from build-plan.yaml — do not edit by hand. -->';

function yamlString(value) {
  return JSON.stringify(value);
}

function uniqueComponentTypes(plan) {
  const types = new Set();
  for (const page of plan.pages || []) {
    for (const component of page.components || []) {
      if (component && component.type) types.add(component.type);
    }
  }
  return [...types].sort();
}

function commerceSummary(plan) {
  const c = plan.commerce;
  if (!c || !c.enabled) return null;
  const parts = [];
  if (c.provider) parts.push(c.provider);
  const checkout = c.checkout || {};
  if (checkout.provider) {
    parts.push('checkout ' + checkout.provider + (checkout.mode ? ' (' + checkout.mode + ')' : ''));
  }
  if (c.currency) parts.push(String(c.currency).toUpperCase());
  return parts.join(' · ');
}

export function renderSiteConcept(plan, { slug }) {
  const title = plan.name || slug;
  const description = (plan.overview || '').replace(/\s+/g, ' ').trim();
  const customDomain = (plan.custom_domain || '').trim();
  const commerce = commerceSummary(plan);
  const pages = (plan.pages || []).map((p) => p.id).filter(Boolean);
  const components = uniqueComponentTypes(plan);

  const tags = ['site'];
  if (commerce) tags.push('commerce');

  let out = '---\n';
  out += 'type: Site\n';
  out += 'title: ' + yamlString(title) + '\n';
  if (description) out += 'description: ' + yamlString(description) + '\n';
  if (customDomain) out += 'resource: ' + yamlString('https://' + customDomain) + '\n';
  out += 'tags: [' + tags.join(', ') + ']\n';
  out += '---\n\n';

  out += GENERATED_NOTE + '\n\n';
  out += '# ' + title + '\n\n';
  if (description) out += description + '\n\n';

  out += '| Field | Value |\n|---|---|\n';
  out += '| Slug | `' + slug + '` |\n';
  out += '| Custom domain | ' + (customDomain ? '`' + customDomain + '`' : '—') + ' |\n';
  if (plan.style) out += '| Style | ' + plan.style + ' |\n';
  out += '| Pages | ' + (pages.length ? pages.join(', ') : '—') + ' |\n';
  out += '| Commerce | ' + (commerce || '—') + ' |\n';
  out += '| Components | ' + (components.length ? components.join(', ') : '—') + ' |\n';

  return out.trimEnd() + '\n';
}

export function generateSiteConcept(buildPlanPath, outPath, slug) {
  const plan = yaml.load(fs.readFileSync(buildPlanPath, 'utf8')) || {};
  const resolvedSlug = slug || plan.slug || path.basename(path.dirname(buildPlanPath));
  fs.mkdirSync(path.dirname(outPath), { recursive: true });
  fs.writeFileSync(outPath, renderSiteConcept(plan, { slug: resolvedSlug }));
  return resolvedSlug;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const [buildPlanPath, outPath, slug] = process.argv.slice(2);
  if (!buildPlanPath || !outPath) {
    console.error('Usage: node generate-site-concept.mjs <build-plan.yaml> <out.md> [slug]');
    process.exit(2);
  }
  const resolved = generateSiteConcept(buildPlanPath, outPath, slug);
  console.log('✓ ' + outPath + ' (Site: ' + resolved + ')');
}
